def evaluate(current_reputation, observation, my_history, round_num):
    """
    Update reputation: cooperators give a diminishing bonus, defectors get a fixed harsh penalty.
    """
    if observation['action'] == 'cooperate':
        # bonus decreases as reputation gets higher (diminishing returns)
        bonus = max(0.05, 0.2 - 0.1 * current_reputation)
        return min(1.0, current_reputation + bonus)
    else:
        # harsh penalty for defection
        return max(-1.0, current_reputation - 0.3)

def decide(recipient_reputation, round_num, my_history):
    """
    Cooperate if recipient reputation > adaptive threshold based on own past cooperation rate.
    Start with full cooperation in early rounds.
    """
    # Cooperate unconditionally in the first 3 rounds
    if round_num < 3:
        return True

    # Compute own cooperation rate (avoid division by zero)
    if len(my_history) > 0:
        coop_rate = sum(my_history) / len(my_history)
        # threshold is lower when I cooperate a lot, higher when I defect often
        threshold = max(0.0, 0.6 - 0.3 * coop_rate)
    else:
        threshold = 0.3

    return recipient_reputation > threshold
